from typing import Any, Dict, List, Union

import boto3

bedrock = boto3.client('bedrock', region_name='us-east-1')


def create_inference_request(model_id: str, prompt: str, max_tokens: int) -> Dict[str, Any]:
    return {
        'modelId': model_id,
        'inputText': prompt,
        'maxTokens': max_tokens
    }


def parse_inference_response(response: Dict[str, Any]) -> str:
    return response['outputText']


def normalize_model_family(model_id: str) -> str:
    model_families = {
        'amazon.titan': 'Titan',
        'anthropic.claude': 'Claude',
        'meta.llama': 'Llama'
    }
    return model_families.get(model_id.split('.')[0], 'Unknown')


def list_available_models() -> List[str]:
    response = bedrock.list_foundation_models()
    return [model['modelId'] for model in response['modelSummaries']]


def select_model_family(model_family: str) -> Union[str, None]:
    available_models = list_available_models()
    for model in available_models:
        if model.startswith(model_family.lower() + '.'):
            return model
    return None

import os
import boto3

# Configuration for AWS Bedrock
AWS_REGION = 'us-west-2'

# Initialize the Bedrock client
bedrock_client = boto3.client('bedrock-runtime', region_name=AWS_REGION)


def select_model_family(model_family):
    """Select a specific model family from AWS Bedrock."""
    if model_family == 'anthropic':
        return 'anthropic.claude-v2'
    elif model_family == 'amazon':
        return 'amazon.titan-text-express-v1'
    else:
        raise ValueError('Unsupported model family')


def perform_inference(model_family, prompt):
    """Perform inference using the selected model family."""
    model_id = select_model_family(model_family)
    response = bedrock_client.invoke_model(
        modelId=model_id,
        body={
            'prompt': prompt,
            'max_tokens': 150
        }
    )
    return response['body']['outputs'][0]['text']

